      let ty = (textureSampleLevel(datTex, samp, q.xz, i32(m4.z), 0.0).xy * 2.0 - 1.0) * k;
      let tz = (textureSampleLevel(datTex, samp, q.xy, i32(m4.z), 0.0).xy * 2.0 - 1.0) * k;
