  let t1 = select(vec3f(1.0, 0.0, 0.0), vec3f(-vh.y, vh.x, 0.0) / sqrt(l2), l2 > 0.0);
  let t2 = cross(vh, t1);
  let r = sqrt(rnd()); let ph = 2.0 * PI * rnd();
  let p1 = r * cos(ph);
  let s = 0.5 * (1.0 + vh.z);
  let p2 = (1.0 - s) * sqrt(1.0 - p1 * p1) + s * r * sin(ph);
  let nh = p1 * t1 + p2 * t2 + sqrt(max(0.0, 1.0 - p1 * p1 - p2 * p2)) * vh;
  return normalize(vec3f(a * nh.x, a * nh.y, max(1e-6, nh.z)));
