  let F = schlick(f0, vh);
  let spec = F * ggxD(a2, nh) * smithG1(a2, nv) * smithG1(a2, nl) / (4.0 * nv * nl);
  let diff = s.base * (1.0 - s.metal) * (1.0 - s.trans) / PI * (1.0 - lum(F) * 0.5);
  var f = (diff + spec) * nl;
  var pdf = lo.d * nl / PI + lo.s * vndfPdf(a2, nv, nh, vh);
